-- Indústria · /dashboard/industrial/apontamento — Apontamento de Produção (Bovinos): chaves de ajuda RD-95 ("?")
-- para os 17 campos do formulário (data, turno, operadores, produção, qualidade SIF e custos do turno).
-- ADITIVO e idempotente: só linhas novas em erp_ajuda_campo (ON CONFLICT DO NOTHING). Nenhuma função/view/policy muda.

INSERT INTO public.erp_ajuda_campo (chave, rota, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum) VALUES
 ('industria.apontamento.data', '/dashboard/industrial/apontamento', 'Data',
  'O dia do turno que você está apontando.', 'Define a que dia pertence a produção e o custo do turno; é a chave para comparar dias e fechar o mês.',
  '14/11/2026.', 'Apontar no dia errado joga a produção para outro dia e distorce o custo diário.'),
 ('industria.apontamento.turno', '/dashboard/industrial/apontamento', 'Turno',
  'O turno trabalhado: A (manhã), B (tarde) ou C (noite).', 'Separa a produção e o custo por turno, para comparar o rendimento de cada equipe.',
  'Turno A (manhã).', 'Lançar tudo num turno só esconde a diferença de desempenho entre as equipes.'),
 ('industria.apontamento.operadores', '/dashboard/industrial/apontamento', 'Operadores',
  'Quantas pessoas trabalharam no turno.', 'Serve para calcular a produção por pessoa e distribuir a mão de obra.',
  '8 operadores.', 'Esquecer de contar quem entrou no meio do turno infla a produtividade por pessoa.'),
 ('industria.apontamento.cabecas_abatidas', '/dashboard/industrial/apontamento', 'Cabeças abatidas',
  'Número de animais abatidos no turno.', 'É a base do custo por cabeça e por quilo e da meta do turno.',
  '120 cabeças.', 'Contar animais condenados como abatidos infla a produção; registre os condenados no campo próprio.'),
 ('industria.apontamento.peso_total_kg', '/dashboard/industrial/apontamento', 'Peso total carcaça (kg)',
  'Peso total das carcaças produzidas no turno, em quilos.', 'É a base do custo por quilo (produto final sempre em kg) e do rendimento de carcaça.',
  '28.500 kg.', 'Informar peso vivo em vez de peso de carcaça distorce o rendimento e o custo/kg.'),
 ('industria.apontamento.rendimento_pct', '/dashboard/industrial/apontamento', 'Rendimento carcaça (%)',
  'Percentual de rendimento da carcaça sobre o peso vivo.', 'Mostra quanto do animal virou carcaça; indicador de eficiência do abate.',
  '52%.', 'Digitar o número sem considerar que é percentual (ex.: 0,52 em vez de 52) zera o indicador.'),
 ('industria.apontamento.horas_efetivas', '/dashboard/industrial/apontamento', 'Horas efetivas',
  'Horas realmente trabalhadas no turno, descontando paradas.', 'Base da produtividade por hora e do rateio da mão de obra.',
  '8 horas.', 'Lançar as horas de escala em vez das horas efetivas esconde o impacto das paradas.'),
 ('industria.apontamento.meta_cab_turno', '/dashboard/industrial/apontamento', 'Meta cabeças turno',
  'Quantas cabeças o turno deveria abater (meta planejada).', 'Serve para comparar o realizado com a meta e medir o atingimento.',
  'Meta 130 cabeças.', 'Meta zerada deixa o indicador de atingimento sem referência.'),
 ('industria.apontamento.paradas_min', '/dashboard/industrial/apontamento', 'Paradas (min)',
  'Minutos totais de parada da linha no turno.', 'Explica queda de produção e desconta das horas efetivas.',
  '35 minutos.', 'Não registrar paradas faz o turno parecer ineficiente sem mostrar o motivo.'),
 ('industria.apontamento.condenados_total', '/dashboard/industrial/apontamento', 'Condenados total',
  'Número de carcaças condenadas na inspeção.', 'Mede a perda por condenação (SIF) e corrige a produção aproveitada.',
  '3 condenados.', 'Somar condenados às cabeças aproveitadas infla a produção boa do turno.'),
 ('industria.apontamento.ph_medio', '/dashboard/industrial/apontamento', 'pH médio',
  'pH médio medido na carcaça.', 'Indicador de qualidade da carne; fora da faixa sinaliza risco de qualidade.',
  'pH 5,8.', 'Registrar uma única medição isolada em vez da média do turno distorce o indicador.'),
 ('industria.apontamento.temp_camara_c', '/dashboard/industrial/apontamento', 'Temp. câmara (°C)',
  'Temperatura média da câmara fria no turno, em graus Celsius.', 'Controle da cadeia de frio; fora da faixa sinaliza risco sanitário.',
  '2 °C.', 'Anotar a temperatura do ambiente em vez da câmara mascara falha de refrigeração.'),
 ('industria.apontamento.custo_animal', '/dashboard/industrial/apontamento', 'Custo animais',
  'Custo total dos animais abatidos no turno, em reais.', 'Maior parcela do custo do turno; entra no custo por cabeça e por quilo.',
  'R$ 180.000.', 'Informar o custo de um animal só, em vez do total do turno, subestima muito o custo.'),
 ('industria.apontamento.custo_mo', '/dashboard/industrial/apontamento', 'Mão de obra',
  'Custo de mão de obra do turno, em reais (com encargos).', 'Parcela do custo do turno ligada às horas efetivas e ao nº de operadores.',
  'R$ 4.500.', 'Esquecer os encargos subestima o custo real da mão de obra.'),
 ('industria.apontamento.custo_energia', '/dashboard/industrial/apontamento', 'Energia',
  'Custo de energia do turno, em reais.', 'Compõe o custo do turno e o custo por quilo produzido.',
  'R$ 1.200.', 'Ratear a conta mensal inteira num só turno distorce o custo do dia.'),
 ('industria.apontamento.custo_insumos', '/dashboard/industrial/apontamento', 'Insumos/outros',
  'Custo de insumos e demais gastos do turno, em reais.', 'Fecha o custo total do turno junto com animais, mão de obra e energia.',
  'R$ 900.', 'Jogar aqui custos que já estão em outro campo conta o mesmo gasto duas vezes.'),
 ('industria.apontamento.receita_turno', '/dashboard/industrial/apontamento', 'Receita do turno (integração)',
  'Receita gerada pela produção do turno, em reais.', 'Comparada com o custo do turno, mostra o resultado do dia.',
  'R$ 210.000.', 'Receita em branco deixa o resultado do turno sem o lado da venda.')
ON CONFLICT (chave) DO NOTHING;
